private AttackResult cookieLoginFlow(String cookieValue) {
    String cookieUsername;
    try {
        cookieUsername = EncDec.decode(cookieValue).toLowerCase();
    } catch (Exception e) {
        return failed(this).output(e.getMessage()).build();
    }
    if (users.containsKey(cookieUsername)) {
        // ✅ 新增：校验 cookie 是否包含该用户的密码哈希（或签名）
        String expectedCookie = EncDec.encode(cookieUsername + "|" + users.get(cookieUsername));
        if (cookieValue.equals(expectedCookie)) {
            if (cookieUsername.equals(ATTACK_USERNAME)) {
                return success(this).build();
            }
            return informationMessage(this)
                .feedback("spoofcookie.cookie-login-success")
                .build();
        }
    }
    return failed(this)
        .feedback("spoofcookie.cookie-login-failed")
        .build();
}

