            pictureId = Integer.parseInt(id);
            if (pictureId < 1 || pictureId > 10) {
                return ResponseEntity.status(HttpStatus.NOT_FOUND).build();
            }
        }
        var catPicture = new File(catPicturesDirectory, pictureId + ".jpg");
        if (catPicture.exists() && catPicture.getCanonicalPath().startsWith(catPicturesDirectory.getCanonicalPath())) {
            return ResponseEntity.ok()
                .contentType(MediaType.parseMediaType(MediaType.IMAGE_JPEG_VALUE))
                .location(new URI("/PathTraversal/random-picture?id=" + pictureId))
                .body(Base64.getEncoder().encode(FileCopyUtils.copyToByteArray(catPicture)));
        }
        return ResponseEntity.status(HttpStatus.NOT_FOUND)
            .location(new URI("/PathTraversal/random-picture?id=" + pictureId))
            .body("Image not found".getBytes());
    } catch (IOException | URISyntaxException | NumberFormatException e) {
        log.error("Image access error", e);
    }
    return ResponseEntity.badRequest().build();
}

