      String regexUsesPlaceholder = "(?=.*\\=\\?.*|.*\\=\\s\\?.*)";
      String regexUsesSetString = "(?=.*setString.*)";
      String regexUsesExecute = "(?=.*execute.*)";
      String regexUsesExecuteUpdate = "(?=.*executeUpdate.*)";

      String codeline = editor.replace("\n", "").replace("\r", "");

