@ResponseStatus(HttpStatus.OK)
@ResponseBody
public AttackResult sendPasswordResetLink(@RequestParam String email, HttpServletRequest request, @RequestHeader(value = "X-CSRF-TOKEN", required = false) String csrfToken) throws URISyntaxException {
    // Validate CSRF token if present (Spring Security auto-injects X-CSRF-TOKEN in thymeleaf forms)
    if (csrfToken == null || !isCsrfTokenValid(request, csrfToken)) {
        throw new AccessDeniedException("Invalid or missing CSRF token");
    }
    if (StringUtils.hasText(email)) {
        String username = email.substring(0, email.indexOf("@"));
        if (StringUtils.hasText(username)) {
            URI uri = new URI(request.getRequestURL().toString());
            Email mail = Email.builder()
                .title("Your password reset link for challenge 7")
                .contents(String.format(TEMPLATE, uri.getScheme() + "://" + uri.getHost(), new PasswordResetLink().createPasswordReset(username, "webgoat")))
                .sender("password-reset@webgoat-cloud.net")
                .recipient(username)
                .time(LocalDateTime.now())
                .build();
            restTemplate.postForEntity(webWolfMailURL, mail, Object.class);
        }
    }
    return success(this).feedback("email.send").feedbackArgs(email).build();
}

private boolean isCsrfTokenValid(HttpServletRequest request, String token) {
    CsrfToken csrfTokenFromRequest = (CsrfToken) request.getAttribute(CsrfToken.class.getName());
    return csrfTokenFromRequest != null && token.equals(csrfTokenFromRequest.getToken());
}

